$('#notifications').onclick=()=>task(async()=>{
 if(rooms[roomId].notify){await api('/rooms/'+roomId+'/unsubscribe',{endpoint:rooms[roomId].pushEndpoint});rooms[roomId].notify=false;save();message('이 방의 차례 알림을 껐습니다.');return;}
 const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('브라우저에서 알림을 허용하면 창을 닫은 뒤에도 차례 알림을 받을 수 있습니다.');
 const registration=await navigator.serviceWorker.register('./online-sw.js',{scope:'./'});if(!registration.active)await navigator.serviceWorker.ready;
 const {publicKey}=await api('/push-key',null,false);if(!publicKey)throw Error('서버의 알림 기능을 준비 중입니다.');
 const bytes=Uint8Array.from(atob(publicKey.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0));const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});
 await api('/rooms/'+roomId+'/subscribe',{subscription:subscription.toJSON(),pageUrl:new URL('online.html',location.href).href});rooms[roomId].notify=true;rooms[roomId].pushEndpoint=subscription.endpoint;save();message('이 방의 내 차례와 턴제 마감 알림을 켰습니다. 기기와 브라우저의 알림 설정에 따라 표시됩니다.');
});
$('#backLobby').onclick=()=>{roomId=null;state=null;draft=null;choice=null;prepared=null;selected=null;if(ws){ws.onclose=null;ws.close();}clearTimeout(socketRetry);clearInterval(poll);$('#table').hidden=true;$('#lobby').hidden=false;$('#onlineTop').hidden=true;document.body.classList.remove('online-entered');history.replaceState(null,'',location.pathname);renderSaved();void refreshList();$('#connection').textContent='방을 선택하세요';};
