$('#confirm').onclick=()=>task(async()=>{if(!prepared?.complete)return;pendingCommand??=command({...draft});const result=await api('/rooms/'+roomId+'/action',pendingCommand);draft=null;prepared=null;choice=null;pendingCommand=null;selected=null;actionType=null;receive(result.snapshot);message('행동을 확정했습니다.');});
