document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]'),filter=e.target.closest('[data-filter]'),inventory=e.target.closest('[data-inventory]'),card=e.target.closest('[data-card]'),action=e.target.closest('[data-action]'),option=e.target.closest('[data-choice]'),resume=e.target.closest('[data-resume]');if(nav){if(!roomId)return;view(nav.dataset.nav);return;}if(filter){cardFilter=filter.dataset.filter;render();return;}if(inventory){personalOwner=state.seat;$('#personalOwner').value=state.seat;view('boardView');render();return;}if(resume){const id=resume.dataset.resume;enter(id,rooms[id].key);return;}if(busy)return;if(e.target.id==='revealReward')task(async()=>{const fixed=structuredClone(draft);await mutate('lock',fixed);draft=structuredClone(state.lock);selected=draft.cardIndex;await makeChoice();});
 if(card&&mine()&&!state.lock){includeVanderbilt=false;const keepType=draft?null:actionType;selected=Number(card.dataset.card);actionType=keepType;draft=null;prepared=null;choice=null;pendingCommand=null;if(actionType)task(async()=>{draft={type:actionType,cardIndex:selected,choices:[]};await makeChoice();});else render();}
 if(action&&mine()&&!state.lock){includeVanderbilt=false;actionType=action.dataset.action;draft=null;prepared=null;choice=null;pendingCommand=null;if(selected==null)render();else task(async()=>{draft={type:actionType,cardIndex:selected,choices:[]};await makeChoice();});}
 if(option&&choice&&mine())task(async()=>{draft.choices.push(Number(option.dataset.choice));await makeChoice();});if(e.target.id==='closeMapInfo')$('#mapInfo').hidden=true;});
$('#personalOwner').onchange=()=>{personalOwner=Number($('#personalOwner').value);if(state?.game)tableUI.render(prepared?.preview||state.game);};document.addEventListener('change',e=>{if(e.target.id==='includeVanderbilt'){includeVanderbilt=e.target.checked;render();}});$('#targetSelectMode').onchange=e=>{targetSelectMode=e.target.value;try{localStorage.setItem(KEY+'-target',targetSelectMode);}catch{}render();};$('#copyLog').onclick=()=>task(async()=>{await navigator.clipboard.writeText($('#logs').innerText);message('기록을 복사했습니다.');});

$('#board').addEventListener('click',e=>{if(busy||Date.now()<ignoreClick)return;const info=e.target.closest('[data-network-info]');if(info&&choice?.kind!=='map'){showOnlineNetworkInfo(board.networkDescriptor(prepared?.preview||state.game,info.dataset.networkInfo),e);return;}const node=e.target.closest('[data-slot],[data-route],[data-oil]'),option=node&&mapOption(node);if(option)task(async()=>{draft.choices.push(option.index);await makeChoice();});else if(node&&!choice)showMapInfo(node);});
$('#board').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){const info=e.target.closest('[data-network-info]');if(info&&choice?.kind!=='map'){e.preventDefault();showOnlineNetworkInfo(board.networkDescriptor(prepared?.preview||state.game,info.dataset.networkInfo));return;}const option=mapOption(e.target);if(option){e.preventDefault();task(async()=>{draft.choices.push(option.index);await makeChoice();});}}});
function showMapInfo(node){const g=prepared?.preview||state?.game;if(!g)return;let text='';if(node.dataset.slot){const c=data.catalog.find(x=>x.id===node.dataset.slot),l=data.locations.find(x=>x.id===c?.parentId),i=Number(node.dataset.slot.split('.').at(-1))-1,p=g.cities[l.name][i];text=l.name+' '+(i+1)+'번 칸\n'+(Number.isInteger(p.owner)?g.players[p.owner].name+' · '+p.industry+' · '+(p.flipped?'뒤집힘':'앞면')+'\n남은 자원: '+Object.entries(p.resources||{}).map(([r,n])=>r+' '+n).join(', '):'건설 가능: '+l.slots[i].join(' / '));}else if(node.dataset.route){const r=data.routes.find(x=>x.id===node.dataset.route),p=g.edges[r.gameId];text=r.from+'—'+r.to+'\n'+(p?g.players[p.owner].name+' · '+core.networks.find(n=>n.id===p.networkId)?.name:'미설치')+'\n'+(r.type==='pipeline'?'기본 오일 '+r.oil:r.bonus||'노선 보너스 없음');}else{const l=data.locations.find(x=>x.id===node.dataset.oil),p=g.setup.oil[l.name];text=(p.revealed?p.value:'미공개 유전')+'\n남은 오일 '+(g.oilCities[l.name]?.resource??g.oilfields[l.name]);}$('#mapInfo').hidden=false;$('#mapInfo').innerHTML='<button id="closeMapInfo" aria-label="정보 닫기">×</button>'+esc(text);}
function zoom(factor){camera.w=Math.min(2000,Math.max(400,camera.w/factor));camera.x=Math.min(2000-camera.w,Math.max(0,camera.x));camera.y=Math.min(2000-camera.w,Math.max(0,camera.y));$('#board').setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.w} ${camera.w}`);}
$('#zoomIn').onclick=()=>zoom(1.3);$('#zoomOut').onclick=()=>zoom(1/1.3);$('#fit').onclick=()=>{camera={x:0,y:0,w:2000};zoom(1);};
$('#mapWrap').addEventListener('wheel',e=>{closeOnlineNetworkInfo();e.preventDefault();zoom(Math.exp(-e.deltaY*.0015));},{passive:false});
$('#mapWrap').addEventListener('pointerdown',e=>{closeOnlineNetworkInfo();if(e.button>0)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});drag={x:e.clientX,y:e.clientY};if(pointers.size===2){const [a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y);ignoreClick=Date.now()+400;}});
$('#mapWrap').addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(pinch)zoom(distance/pinch);pinch=distance;ignoreClick=Date.now()+400;}else if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2){const scale=camera.w/$('#mapWrap').clientWidth;camera.x-=dx*scale;camera.y-=dy*scale;zoom(1);ignoreClick=Date.now()+250;}}drag={x:e.clientX,y:e.clientY};});for(const event of ['pointerup','pointercancel','pointerleave'])$('#mapWrap').addEventListener(event,e=>{pointers.delete(e.pointerId);drag=null;pinch=null;});
