const params=new URLSearchParams(location.search),id=params.get('room')?.toUpperCase(),resume=new URLSearchParams(location.hash.slice(1)).get('resume');if(id&&/^[A-Z2-9]{8}$/.test(id)){$('#roomCode').value=id;if(resume&&/^[a-zA-Z0-9_-]{32,100}$/.test(resume)){rooms[id]={key:resume,name:'재접속'};save();history.replaceState(null,'',location.pathname+'?room='+id);}else{try{const tabKey=sessionStorage.getItem(KEY+'-'+id);if(tabKey)rooms[id]={...rooms[id],key:tabKey,name:rooms[id]?.name||'재접속'};}catch{}}if(rooms[id]?.key&&rooms[id].name)enter(id,rooms[id].key);}
